SELECT  FROM public.gateway_url_exposure_t0
WHERE tenant_id = 0 AND deleted_at IS NULL AND owner_tenant_id = #{owner}
  AND gateway_group_id = #{groupId} AND route_id = #{routeId}

SELECT id FROM public.gateway_url_exposure_t0
WHERE tenant_id = 0 AND deleted_at IS NULL AND owner_tenant_id = #{owner}
  AND reconcile_status IN ('PENDING', 'SYNCED') AND id > #{afterId}
ORDER BY id ASC LIMIT #{limit}

SELECT  FROM public.gateway_url_exposure_t0
WHERE tenant_id = 0 AND deleted_at IS NULL AND cluster_id = #{cluster}
  AND gateway_namespace = #{gatewayNamespace} AND gateway_name = #{gatewayName}
  AND listener_name = #{listenerName} AND id > #{afterId}
ORDER BY id ASC LIMIT #{limit}
